import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const inkColor = new Color(colors.ink);
  const surfaceColor = new Color(colors.surface);
  const accentColor = new Color(colors.accent);
  const paperColor = new Color(colors.paper);

  // 1. Local backing panel to act as a mini-stage and avoid FLAT_VOID
  const panelGeom = new PlaneGeometry(2.8, 1.8);
  const panelMat = new MeshBasicNodeMaterial();

  // Custom TSL Shader for the panel backdrop: Vertical gradient + signal-red top border edge accent
  const uvNode = uv();
  const gradNode = mix(
    vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b),
    vec3(inkColor.r, inkColor.g, inkColor.b),
    uvNode.y
  );

  // Highlight top border with accent color
  const borderEdge = smoothstep(0.96, 0.99, uvNode.y);
  const finalColorNode = mix(
    gradNode,
    vec3(accentColor.r, accentColor.g, accentColor.b),
    borderEdge
  );

  panelMat.colorNode = finalColorNode;

  const panelMesh = new Mesh(panelGeom, panelMat);
  group.add(panelMesh);

  // 2. Load and render decorative orb image
  const decorationGroup = new Group();
  decorationGroup.position.set(0, 0, 0.01);
  group.add(decorationGroup);

  if (config.imageUrl) {
    const decGeom = new PlaneGeometry(1.2, 1.2);
    const decMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0.18,
      depthWrite: false
    });

    ctx.textureLoader.loadTexture(config.imageUrl)
      .then((tex) => {
        decMat.map = tex;
        decMat.needsUpdate = true;
      })
      .catch(() => {});

    const decMesh = new Mesh(decGeom, decMat);
    decMesh.position.set(0.6, -0.2, 0.01);
    decorationGroup.add(decMesh);
  }

  // 3. Render "Pricing 1" Label Text via fontAtlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelText = items.find(t => t.text)?.text ?? "Pricing 1";

  const textMesh = ctx.fontAtlas.createText(labelText, {
    fontSize: 34,
    color: colors.paper,
    align: 'center'
  });

  // Center alignment styling
  textMesh.position.set(0, 0.1, 0.02);
  group.add(textMesh);

  // Subtle decorative mono subline to match Neo-Atelier aesthetic
  const subTextMesh = ctx.fontAtlas.createText("ATELIER SELECT", {
    fontSize: 10,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 6
  });
  subTextMesh.position.set(0, -0.4, 0.02);
  group.add(subTextMesh);

  // 4. Subtle entrance animation (weighted-settle pattern)
  group.position.y += 0.3;
  group.scale.set(0.95, 0.95, 1);

  const tl = gsap.timeline();
  tl.to(group.position, {
    y: '-=0.3',
    duration: 0.9,
    ease: 'power4.out'
  });
  tl.to(group.scale, {
    x: 1,
    y: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  // Apply any config-supplied cinematic primitives if requested
  const primitiveInstances = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((p) => {
      const prim = ctx.primitives[p.name];
      if (typeof prim === 'function') {
        const inst = prim(group, p.params);
        if (inst) primitiveInstances.push(inst);
      }
    });
  }

  // Cleanup handler
  group.userData = {
    cleanup() {
      tl.kill();
      primitiveInstances.forEach((inst) => {
        if (typeof inst.cleanup === 'function') inst.cleanup();
      });
      panelGeom.dispose();
      panelMat.dispose();
    }
  };

  return group;
}
